<script setup lang="ts">import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import { Head, useForm } from '@inertiajs/vue3'; const props=defineProps<{student?:any}>(); const form=useForm({first_name:props.student?.first_name||'',middle_name:props.student?.middle_name||'',last_name:props.student?.last_name||'',preferred_name:props.student?.preferred_name||'',status:props.student?.status||'active'}); const submit=()=>props.student?form.patch(route('students.update',props.student.id)):form.post(route('students.store'));</script>
<template><Head :title="student?'Edit student':'Add student'"/><AuthenticatedLayout><h1 class="h2">{{ student?'Edit student':'Add student' }}</h1><div class="card mt-4"><form class="card-body" @submit.prevent="submit"><div class="row g-3"><div class="col-md-6"><label class="form-label" for="first_name">First name</label><input id="first_name" v-model="form.first_name" class="form-control" required><div class="text-danger small">{{form.errors.first_name}}</div></div><div class="col-md-6"><label class="form-label" for="last_name">Last name</label><input id="last_name" v-model="form.last_name" class="form-control" required><div class="text-danger small">{{form.errors.last_name}}</div></div><div class="col-md-6"><label class="form-label" for="middle_name">Middle name <span class="text-secondary">(optional)</span></label><input id="middle_name" v-model="form.middle_name" class="form-control"></div><div class="col-md-6"><label class="form-label" for="preferred_name">Preferred name <span class="text-secondary">(optional)</span></label><input id="preferred_name" v-model="form.preferred_name" class="form-control"></div><div v-if="student" class="col-md-6"><label class="form-label" for="student_status">Status</label><select v-if="student.status !== 'archived'" id="student_status" v-model="form.status" class="form-select"><option>active</option><option>inactive</option></select><input v-else id="student_status" value="archived" class="form-control" disabled></div></div><button class="btn btn-primary mt-4" :disabled="form.processing"><span v-if="form.processing" class="spinner-border spinner-border-sm me-2" aria-hidden="true"></span>Save student</button></form></div></AuthenticatedLayout></template>
